// Hợp nhất phát hiện bằng LUẬT, không bằng model.
// Quy tắc "bằng chứng hoặc im lặng": BLOCKER không có file:dòng thì bị loại.
// Mỗi item là JSON mà agent-runner trả về từ POST /run: { role, exit, text, status }.
const RE = /\[?(BLOCKER|CRITICAL|MAJOR|MINOR|NIT)\]?\s*([\w./-]+:\d+)?\s*[|:-]?\s*(.+)/i;
const RANK = { CRITICAL: 5, BLOCKER: 4, MAJOR: 3, MINOR: 2, NIT: 1 };

const byKey = new Map();
for (const item of $input.all()) {
  const payload = item.json || {};
  for (const line of String(payload.text || '').split('\n')) {
    const m = RE.exec(line);
    if (!m) continue;
    const sev = m[1].toUpperCase();
    const loc = m[2] || '';
    if ((sev === 'BLOCKER' || sev === 'CRITICAL') && !loc) continue;
    const key = `${loc}|${(m[3] || '').slice(0, 60).toLowerCase()}`;
    const prev = byKey.get(key);
    if (prev) { prev.votes += 1; if (RANK[sev] > RANK[prev.severity]) prev.severity = sev; }
    else byKey.set(key, { severity: sev, location: loc, detail: m[3].trim(), votes: 1, role: payload.role });
  }
}

const findings = [...byKey.values()].sort((a, b) => RANK[b.severity] - RANK[a.severity] || b.votes - a.votes);
const blockers = findings.filter(f => f.severity === 'BLOCKER' || f.severity === 'CRITICAL');

const body = [
  '## Thẩm định tự động của Agent Fleet', '',
  blockers.length ? `**${blockers.length} mục chặn merge.**` : '**Không có mục chặn merge.**', '',
  '| Mức | Vị trí | Vấn đề | Đồng thuận |', '|---|---|---|---|',
  ...findings.slice(0, 40).map(f => `| ${f.severity} | \`${f.location || '—'}\` | ${f.detail.replace(/\|/g, '\\|').slice(0, 200)} | ${f.votes}/3 |`),
  '', '_Ba model của ba nhà cung cấp khác nhau cùng soi diff này. Cột “đồng thuận” cho biết bao nhiêu model cùng nêu một vấn đề — mục 3/3 gần như chắc chắn là thật._',
].join('\n');

return [{ json: { findings, blockerCount: blockers.length, body, state: blockers.length ? 'failure' : 'success' } }];
